import{_ as e,o as a,c as d,ag as o}from"./chunks/framework.C5oN-8Wt.js";const m=JSON.parse('{"title":"复数加法器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.3.0-alpha/modules/complex_add/index.md","filePath":"v0.3.0-alpha/modules/complex_add/index.md"}'),r={name:"v0.3.0-alpha/modules/complex_add/index.md"};function l(h,t,n,c,i,p){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="复数加法器" tabindex="-1">复数加法器 <a class="header-anchor" href="#复数加法器" aria-label="Permalink to &quot;复数加法器&quot;">​</a></h1><p>适用：v0.3.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>complex_add</code> · 模块定义版本：5</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>逐 item、逐分量相加复数输入。实部相加、虚部相加，因此相量的大小与方向共同决定结果；两个等幅反相输入可以相互抵消。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>复数信号源 1.out → 复数加法器.in1</code>，<code>复数信号源 2.out → 复数加法器.in2</code>。可增加输入路数加入复数噪声，所有声明的流输入都应接线。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in1</code>（输入 1）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输入</td><td><code>in2</code>（输入 2）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>out</code>（输出）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>各路需要相同的复数向量长度和实际 item 速率。若使用向量，输出仍保留同样长度，每个分量只与其他输入的对应分量相加。</p><p>相加不是把两个幅度读数相加：存在相位差时，结果可能增强、抵消或形成拍频。用 I/Q 图和频谱一起观察，比仅看瞬时模长更容易理解。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>输入路数<br><code>num_inputs</code></td><td><code>2</code></td><td>范围 1 至 1024；当前画布支持 1–1024 路。修改后须重新准备，缩减前请先解除相关连线和工具绑定。</td><td>重新准备</td></tr><tr><td>每个 item 的向量长度<br><code>vlen</code></td><td><code>1</code></td><td>范围 1 至 1024；Master 当前容量限制为 1–1024；采样率按 item 计。</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>计算参数或结构变化后，先停止，再重新准备和运行。</p><p>输入路数与向量长度属于运行结构，改变后重新准备。缩减端口前解除受影响的连线和工具绑定；草稿编辑不会重构当前图。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="复数处理与-i-q-往返" tabindex="-1">复数处理与 I/Q 往返 <a class="header-anchor" href="#复数处理与-i-q-往返" aria-label="Permalink to &quot;复数处理与 I/Q 往返&quot;">​</a></h3><p><a href="../../../downloads/v0.3.0-alpha/complex-iq.cnsproj" download>下载 complex-iq.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 2048 item；重新打开工程后需再次运行以取得数据。</p><p>复数处理与 I/Q 往返</p><ul><li>观察复数旋转相量、乘 j 的相位变化及 I/Q 分解再合成；复数频谱保留正负频率。</li></ul><p>复数处理示例中的加法器接收两个不同频率的相量及复数噪声。查看其 I/Q 输出和双边频谱，再比较三种滤波支路。所有分支来自同一实际混合流，便于对照选频效果。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>两路都有输出，和却接近零？</strong> 检查它们的相位关系，反相可以抵消。</p><p><strong>能直接接一条实数源吗？</strong> 端口类型不匹配。需要明确构造 I/Q 后，再作为复数输入使用。</p>',26)])])}const u=e(r,[["render",l]]);export{m as __pageData,u as default};
